import type { HTMLAttributes, ReactNode } from 'react'

import { cx } from '~/lib/cx'
import styles from './blockquote.module.scss'

export interface BlockquoteProps extends HTMLAttributes<HTMLQuoteElement> {
  cite?: ReactNode
  tone?: 'default' | 'accent'
}

/** Editorial pull quote with an optional attribution. */
export function Blockquote({
  cite,
  tone = 'default',
  className,
  children,
  ...props
}: BlockquoteProps) {
  return (
    <blockquote
      className={cx(styles.root, tone === 'accent' && styles.accent, className)}
      {...props}
    >
      <div className={styles.body}>{children}</div>
      {cite ? <footer className={styles.cite}>{cite}</footer> : null}
    </blockquote>
  )
}

@use '../../styles' as vz;

.root {
  margin: 0;
  padding: vz.space(5) vz.space(6);
  border-left: 3px solid vz.color('primary');
  border-radius: 0 vz.radius('lg') vz.radius('lg') 0;
  background: vz.color('muted');
  color: vz.color('foreground');
}

.accent {
  background: vz.color('primary', 0.08);
  border-left-color: vz.color('primary');
}

.body {
  font-size: vz.font-size('lg');
  line-height: 1.6;
}

.cite {
  margin-top: vz.space(3);
  color: vz.color('muted-foreground');
  font-size: vz.font-size('sm');
}
